import json
G=[[1]*23 for _ in range(29)]
# original color-3 figure
for c in list(range(10,19))+[20,21]: G[13][c]=3
for r in (14,16,17):
    for c in (10,13,21): G[r][c]=3
for r in range(15,22):
    for c in (10,21): G[r][c]=3
for c in range(10,22): G[22][c]=3
# For each line containing >=3 original color-3 marks, mark the gaps between its extremes with 2.
for r in range(29):
    cols=[c for c in range(23) if G[r][c]==3]
    if len(cols)>=3:
        for c in range(min(cols),max(cols)+1):
            if G[r][c]==1: G[r][c]=2
for c in range(23):
    rows=[r for r in range(29) if G[r][c]==3]
    if len(rows)>=3:
        for r in range(min(rows),max(rows)+1):
            if G[r][c]==1: G[r][c]=2
print(len(G), {len(x) for x in G})
print(json.dumps(G,separators=(',',':')))

